import{seedRecipes}from'./data.js';const STATE_KEY='family-cookbook:v2',LEGACY_USER_KEY='family-cookbook:user-recipes:v1',COOK_KEY='family-cookbook:cook-progress:v1';const clone=value=>JSON.parse(JSON.stringify(value));const id=()=>`r-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;const legacyToRecipe=(raw,index)=>{const title=String(raw.title??'').trim();if(!title)return null;const createdAt=Number(raw.createdAt)||Date.now()-index;const ingredientSectionsRaw=Array.isArray(raw.ingredientSections)?raw.ingredientSections:null;const directionSectionsRaw=Array.isArray(raw.directionSections)?raw.directionSections:null;const flatIngredients=Array.isArray(raw.ingredients)?raw.ingredients.map(String):[];const flatDirections=Array.isArray(raw.directions)?raw.directions.map(String):[];const ingredientSections=(ingredientSectionsRaw?.length?ingredientSectionsRaw:[{title:'Ingredients',items:flatIngredients}]).map((section,s)=>{const items=Array.isArray(section.items)?section.items.map(String):[];return{id:`${id()}-is-${s}`,title:String(section.title??'Ingredients'),ingredients:items.map((text,i)=>({id:`${id()}-i-${i}`,raw:text,name:text.replace(/^[\d¼½¾⅓⅔⅛⅜⅝⅞\s/.-]+/,'').trim()||text}))}});const directionSections=(directionSectionsRaw?.length?directionSectionsRaw:[{title:'Directions',steps:flatDirections}]).map((section,s)=>{const steps=Array.isArray(section.steps)?section.steps.map(String):[];return{id:`${id()}-ds-${s}`,title:String(section.title??'Directions'),steps:steps.map((text,i)=>({id:`${id()}-d-${i}`,text}))}});const meta=raw.meta&&typeof raw.meta==='object'?raw.meta:{};const smokerRaw=raw.smoker&&typeof raw.smoker==='object'?raw.smoker:undefined;const smoker=smokerRaw?{pitTemperatureF:Number(smokerRaw.temperatureF)||undefined,wood:String(smokerRaw.wood??'')||undefined,smoke:String(smokerRaw.smoke??'')||undefined,targetInternalF:String(smokerRaw.targetInternalF??'')||undefined,time:String(smokerRaw.time??'')||undefined,finish:String(smokerRaw.finish??'')||undefined}:undefined;return{id:String(raw.id??id()),title,category:String(raw.category??'Family recipes'),image:String(raw.image??'')||undefined,servings:Number(String(meta.yield??'').match(/\d+/)?.[0]??0)||4,prepMinutes:Number(meta.prepMinutes)||undefined,cookMinutes:Number(meta.cookMinutes)||undefined,cookLabel:String(meta.cookLabel??'')||undefined,marinate:String(meta.marinate??'')||undefined,tags:[],collections:[String(raw.category??'Family recipes')],ingredientSections,directionSections,smoker,pitNotes:String(raw.pitNotes??'')||undefined,note:String(raw.note??'')||undefined,notes:[],history:[{id:`${id()}-migration`,at:Date.now(),summary:'Migrated from Family Cookbook v1'}],favorite:false,createdAt,updatedAt:createdAt}};export const loadState=()=>{try{const stored=JSON.parse(localStorage.getItem(STATE_KEY)??'null');if(stored?.version===2&&Array.isArray(stored.recipes))return stored}catch{}const recipes=clone(seedRecipes);try{const legacy=JSON.parse(localStorage.getItem(LEGACY_USER_KEY)??'[]');if(Array.isArray(legacy))legacy.forEach((value,index)=>{if(!value||typeof value!=='object')return;const migrated=legacyToRecipe(value,index);if(migrated&&!recipes.some(recipe=>recipe.title.toLowerCase()===migrated.title.toLowerCase()))recipes.unshift(migrated)})}catch{}const state={version:2,recipes,grocery:[]};saveState(state);return state};export const saveState=state=>localStorage.setItem(STATE_KEY,JSON.stringify(state));export const saveCookProgress=progress=>{if(!progress)localStorage.removeItem(COOK_KEY);else localStorage.setItem(COOK_KEY,JSON.stringify(progress))};export const loadCookProgress=()=>{try{const progress=JSON.parse(localStorage.getItem(COOK_KEY)??'null');return progress?.recipeId?progress:null}catch{return null}};
